import React, { useEffect, useMemo, useState } from 'react';
import NotificationStrip from 'webapp/components/NotificationStrip';
import userPrefs from 'webapp/lib/userPrefs';
import { useDashboardConfig } from 'webapp/dashboard/useDashboardConfig';

type Banner = {
  campaignId?: string;
  id?: string;
  message?: string;
  // other fields as returned by /api/marketing/active-banner
};

function useAnnouncementDismissal(campaignId?: string) {
  const key = useMemo(() => (campaignId ? `dashboardBannerDismissed:${campaignId}` : null), [campaignId]);

  const [dismissed, setDismissed] = useState<boolean>(() => {
    if (!key) return false;
    try {
      return Boolean(userPrefs.get(key));
    } catch {
      return false;
    }
  });

  useEffect(() => {
    if (!key) {
      setDismissed(false);
      return;
    }
    try {
      setDismissed(Boolean(userPrefs.get(key)));
    } catch {
      setDismissed(false);
    }
  }, [key]);

  const dismiss = () => {
    if (!key) return;
    try {
      userPrefs.set(key, true);
    } catch {
      // swallow errors to keep behavior silent on older browsers
    }
    setDismissed(true);
  };

  return { dismissed, dismiss };
}

export default function AnnouncementBanner(): JSX.Element | null {
  const { activeBanner } = useDashboardConfig() as { activeBanner?: Banner } || {};
  const campaignId = activeBanner?.campaignId ?? activeBanner?.id ?? undefined;

  // If there's no active banner, behave like today (render nothing).
  if (!activeBanner || !campaignId) return null;

  const { dismissed, dismiss } = useAnnouncementDismissal(campaignId);

  if (dismissed) return null;

  return (
    <NotificationStrip onClose={dismiss}>
      {/* render whatever message/content the banner provides */}
      {activeBanner.message ?? null}
    </NotificationStrip>
  );
}
```

