Append these tests to the existing file (or add them if you maintain grouped tests). They mock the prefs and the dashboard hook and stub NotificationStrip to expose a deterministic close button for interactions.

```tsx
import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import AnnouncementBanner from '../AnnouncementBanner';

// mock userPrefs
const mockGet = jest.fn();
const mockSet = jest.fn();
jest.mock('webapp/lib/userPrefs', () => ({
  __esModule: true,
  default: {
    get: (k: string) => mockGet(k),
    set: (k: string, v: any) => mockSet(k, v),
  },
}));

// mock useDashboardConfig hook
jest.mock('webapp/dashboard/useDashboardConfig', () => ({
  useDashboardConfig: jest.fn(),
}));
import { useDashboardConfig } from 'webapp/dashboard/useDashboardConfig';

// stub NotificationStrip so we can click a predictable close button
jest.mock('webapp/components/NotificationStrip', () => {
  return {
    __esModule: true,
    default: ({ children, onClose }: any) => (
      <div data-testid="notification">
        <button onClick={onClose}>close</button>
        <div>{children}</div>
      </div>
    ),
  };
});

describe('AnnouncementBanner persistence', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  test('hide-on-close: banner is removed immediately and preference is set', () => {
    // active banner for campaign-1, prefs report not dismissed
    (useDashboardConfig as jest.Mock).mockReturnValue({
      activeBanner: { campaignId: 'campaign-1', message: 'Sale now on!' },
    });
    mockGet.mockReturnValueOnce(undefined);

    render(<AnnouncementBanner />);

    expect(screen.getByText('Sale now on!')).toBeInTheDocument();

    fireEvent.click(screen.getByText('close'));

    // banner should disappear from DOM
    expect(screen.queryByText('Sale now on!')).not.toBeInTheDocument();

    // userPrefs.set called with the right key
    expect(mockSet).toHaveBeenCalledWith('dashboardBannerDismissed:campaign-1', true);
  });

  test('stay-hidden-on-refresh for same campaignId', () => {
    (useDashboardConfig as jest.Mock).mockReturnValue({
      activeBanner: { campaignId: 'campaign-1', message: 'Sale now on!' },
    });

    // prefs indicates this campaign already dismissed
    mockGet.mockReturnValue(true);

    render(<AnnouncementBanner />);

    // banner should not render
    expect(screen.queryByTestId('notification')).not.toBeInTheDocument();
    expect(mockSet).not.toHaveBeenCalled();
  });

  test('show-again-for-new-campaign even if previous was dismissed', () => {
    // simulate prefs: dismissed for campaign-1 only
    mockGet.mockImplementation((key: string) =>
      key === 'dashboardBannerDismissed:campaign-1' ? true : undefined
    );

    // Now the API returns a new campaign (campaign-2)
    (useDashboardConfig as jest.Mock).mockReturnValue({
      activeBanner: { campaignId: 'campaign-2', message: 'New campaign message' },
    });

    render(<AnnouncementBanner />);

    // new campaign should be shown even though an older one was dismissed
    expect(screen.getByText('New campaign message')).toBeInTheDocument();
  });
});
```

Notes:
- I used userPrefs.get/set as the existing thin wrapper; tests mock those functions so behavior is verified without touching localStorage.
- NotificationStrip is stubbed in tests to guarantee a "close" button; production code continues to use the real shared component.
- The component silently swallows prefs/localStorage errors to preserve current silent behavior when the API returns nothing or on older browsers.

I'll update the AnnouncementBanner to import the local hook and tighten the tests by mocking NotificationStrip with an accessible close button; see the exact changed files below.

